  white-space: nowrap !important;
}

/* 名字右侧的认证勾图标与 @角色名 */
.chat-detail-screen .chat-header-title::after {
  content: "@" var(--char-name) !important; /* ✏️【可修改文字】：默认自动读取角色真名，若想固定可改为 content: "@你的文字" !important; */
  display: inline-flex !important;
  align-items: center !important;
  height: 14px !important;
  margin-left: 6px !important;  /* ★【认证标与名字的左右间距】 */
