/* ==========================================================
   1. 顶栏(只匹配带头像昵称区的聊天页顶栏)
   ========================================================== */
.chat-detail-screen :is(.chat-header-custom, .glass-header):has(.header-profile-section){
  position:relative !important; transform:none !important;
  box-sizing:border-box !important;
  height:calc(var(--ry-top) + var(--ry-head-h)) !important;
  min-height:calc(var(--ry-top) + var(--ry-head-h)) !important;
  max-height:none !important;
  padding:0 !important; margin:0 !important;
  background:var(--ry-head-bg) !important; background-image:none !important;
  border:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  overflow:hidden !important; pointer-events:auto !important;
}
.chat-detail-screen .chat-header-custom:has(.header-profile-section){
  border-bottom:1px solid var(--ry-head-line) !important;
}
.chat-detail-screen .chat-header-custom:has(.header-profile-section)::before,
.chat-detail-screen .chat-header-custom:has(.header-profile-section)::after{ content:none; }

.chat-detail-screen .glass-header:has(.header-profile-section) *:has(:is(.header-btn-back, .header-btn-info, .header-btn-phone, .header-btn-video)){
  position:static !important; transform:none !important; filter:none !important;
  contain:none !important; z-index:auto !important;
  visibility:visible !important; opacity:1 !important; pointer-events:auto !important;
}

.chat-detail-screen .glass-header:has(.header-profile-section)::before{
  content:"" !important; display:block !important; position:absolute !important;
  left:12px; right:12px; top:calc(var(--ry-top) + 4px); height:72px;
  background:var(--ry-card) !important; border:1px solid var(--ry-card-line) !important;
  border-radius:10px; box-sizing:border-box;
  pointer-events:none; z-index:1;
}
.chat-detail-screen .glass-header:has(.header-profile-section)::after{
  content:"搜尋" !important; display:flex !important; position:absolute !important;
  left:12px; right:12px; top:calc(var(--ry-top) + 84px); height:32px;
  align-items:center; justify-content:center; box-sizing:border-box;
  padding-left:22px;
  background:var(--ry-card) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%239a9a9a' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><line x1='21' y1='21' x2='16.5' y2='16.5'/></svg>") no-repeat calc(50% - 20px) center / 14px 14px !important;
  border:1px solid var(--ry-search-line) !important; border-radius:10px;
  color:var(--ry-search-ink); font-size:14px; letter-spacing:.02em; line-height:1;
  pointer-events:none; z-index:2;
}

.chat-detail-screen .header-profile-section{
  position:static !important; transform:none !important;
  margin:0 !important; padding:0 !important; background:transparent !important;
}
.chat-detail-screen .header-profile-section::after{
  content:var(--ry-sub-text) !important; display:block !important;
  position:absolute !important;
  left:32px; top:calc(var(--ry-top) + 56px); max-width:66vw;
  font-size:11px; line-height:14px; color:var(--ry-sub);
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; letter-spacing:.02em;
  pointer-events:none; z-index:4;
}
.chat-detail-screen .header-profile-section::before{ content:none !important; }
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-subtitle{ display:none !important; }

.chat-detail-screen .header-avatar-container{
  display:block !important; position:absolute !important;
  left:32px !important; top:calc(var(--ry-top) + 10px) !important;
  width:40px !important; height:40px !important; min-width:40px !important;
  margin:0 !important; padding:0 !important; transform:none !important;
  border:1px solid #e0e0e0 !important; border-radius:9px !important;
  box-sizing:border-box !important; box-shadow:none !important;
  overflow:hidden !important; z-index:3 !important;
}
.chat-detail-screen .header-avatar-container .chat-header-avatar,
.chat-detail-screen .header-avatar-container img{
  width:100% !important; height:100% !important; min-width:0 !important;
  border:0 !important; border-radius:0 !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}

.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-back, .header-btn-info, .header-btn-phone, .header-btn-video){
  display:block !important; position:absolute !important;
  right:auto; left:auto; bottom:auto !important;
  min-width:0 !important; min-height:0 !important;
  padding:0 !important; margin:0 !important; transform:none !important;
  background:transparent !important; background-image:none !important;
  border:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:transparent !important; opacity:1 !important; visibility:visible !important;
  pointer-events:auto !important; cursor:pointer !important; z-index:8 !important;
  -webkit-tap-highlight-color:transparent !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-back, .header-btn-info, .header-btn-phone, .header-btn-video)::before{ content:none !important; }
.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-info, .header-btn-phone, .header-btn-video) > *,
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-back > *:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){
  opacity:0 !important; pointer-events:none !important;
}

.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-back{
  left:32px !important; top:calc(var(--ry-top) + 10px) !important;
  width:40px !important; height:40px !important; border-radius:9px !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-back::after{ content:none !important; }

.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-title{
  position:absolute !important;
  left:84px !important; top:calc(var(--ry-top) + 10px) !important;
  transform:none !important; margin:0 !important; padding:0 !important;
  max-width:40vw !important;
  background:transparent !important; border:0 !important; text-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:var(--ry-name) !important; font-size:14px !important; font-weight:700 !important;
  line-height:18px !important;
  white-space:nowrap !important; overflow:hidden !important; text-overflow:ellipsis !important;
  z-index:4 !important;
}
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-title::before,
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-title::after{ content:none !important; }

.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-info{
  right:24px !important; top:calc(var(--ry-top) + 7px) !important;
  width:40px !important; height:24px !important; border-radius:0 !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-info::after{
  content:"现在" !important; position:absolute; inset:0;
  display:flex; align-items:center; justify-content:flex-end;
  font-size:13px; color:var(--ry-now); white-space:nowrap; line-height:1;
  pointer-events:none;
}
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-video{
  right:68px !important; top:calc(var(--ry-top) + 5px) !important;
  width:34px !important; height:28px !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-phone{
  right:104px !important; top:calc(var(--ry-top) + 5px) !important;
  width:34px !important; height:28px !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-phone, .header-btn-video)::after{ content:none !important; }

/* ==========================================================
   2. 消息  气泡 4px 方角 · 对方浅灰 / 我方白 · 行间距 16px
            头像 30px 圆角 4px · 头像下挂韩语小标签
   ========================================================== */
.msg-bubble-wrapper{
  margin-top:var(--ry-gap) !important; margin-bottom:0 !important;
  padding-top:0 !important; padding-bottom:0 !important;
}
.msg-bubble-wrapper:first-child{ margin-top:0 !important; }

.bubble-me-custom, .bubble-them-custom,
.bubble-deco-me, .bubble-deco-them,
.msg-bubble-container, .msg-content-stack{ overflow:visible !important; }

.bubble-them-custom,
.bubble-me-custom{
  position:relative !important; box-sizing:border-box !important;
  border-radius:4px !important; box-shadow:none !important; text-shadow:none !important;
  padding:5px 10px !important; color:var(--ry-ink) !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
.bubble-them-custom{
  background:var(--ry-ta-bg) !important; background-image:none !important;
  border:1px solid var(--ry-ta-line) !important;
}
.bubble-me-custom{
  background:var(--ry-me-bg) !important; background-image:none !important;
  border:1px solid var(--ry-me-line) !important;
}
.bubble-them-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *),
.bubble-me-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--ry-ink) !important; }
.bubble-me-custom::before, .bubble-me-custom::after,
.bubble-them-custom::before, .bubble-them-custom::after{ content:none !important; }

.bubble-them-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *),
.bubble-me-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *){
  max-width:none !important;
}
.bubble-them-custom, .bubble-me-custom,
.bubble-them-custom :is(p,span,div), .bubble-me-custom :is(p,span,div){
  word-break:normal !important; overflow-wrap:anywhere !important;
  line-break:auto !important; text-wrap:wrap !important;
}
:is(.bubble-them-custom,.bubble-me-custom):has([class*="card"], .msg-image-wrapper){
  background:transparent !important; border:0 !important; padding:0 !important;
}

:is(.msg-avatar-them-container, .msg-avatar-me-container){
  position:relative !important;
  width:var(--ry-avatar) !important; height:var(--ry-avatar) !important;
  min-width:var(--ry-avatar) !important;
  border:0 !important; box-shadow:none !important; overflow:visible !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner, .msg-avatar-custom){
  width:var(--ry-avatar) !important; height:var(--ry-avatar) !important;
  min-width:var(--ry-avatar) !important;
  border:0 !important; border-radius:var(--ry-avatar-r) !important;
  box-shadow:none !important; overflow:hidden !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}
.msg-avatar-me-container:has(img, .msg-avatar-me-inner)::after,
.msg-avatar-them-container:has(img, .msg-avatar-them-inner)::after{
  position:absolute; left:50%; top:calc(100% + 2px); transform:translateX(-50%);
  font-size:10px; font-weight:700; color:var(--ry-search-ink);
  white-space:nowrap; letter-spacing:.02em; line-height:1.2;
  pointer-events:none; z-index:2;
}
.msg-avatar-me-container:has(img, .msg-avatar-me-inner)::after{ content:var(--ry-tag-me) !important; }
.msg-avatar-them-container:has(img, .msg-avatar-them-inner)::after{ content:var(--ry-tag-ta) !important; }

/* ==========================================================
   3. 引用  气泡上方:左侧圆形小头像 + 名字内容同行 + 右侧细线灰色转发图标
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:flex !important; order:-1 !important;
  position:relative !important; box-sizing:border-box !important;
  flex-flow:row nowrap !important; align-items:center !important; gap:4px !important;
  width:fit-content !important; min-width:0 !important; max-width:66vw !important;
  margin:0 0 5px 0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; border-left:0 !important;
  border-radius:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  transform:none !important; clip-path:none !important; opacity:1 !important;
  line-height:1.3 !important; white-space:nowrap !important; overflow:visible !important;
}
.msg-reply-detached-me{ align-self:flex-end !important; margin-left:auto !important; }
.msg-reply-detached-them{ align-self:flex-start !important; margin-right:auto !important; }
.msg-reply-block-detached::before{
  content:"" !important; flex:0 0 16px; width:16px; height:16px;
  border-radius:50%; background-color:var(--ry-card-ic);
  background-size:cover; background-position:center; background-repeat:no-repeat;
  margin-right:2px; pointer-events:none;
}
.msg-reply-detached-me::before{ background-image:var(--char-avatar) !important; }
.msg-reply-detached-them::before{ background-image:var(--user-avatar) !important; }
.msg-reply-block-detached::after{
  content:"" !important; flex:0 0 17px; width:17px; height:17px; margin-left:3px;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke-linecap='round' stroke-linejoin='round'><path d='M12 3.2a8.8 8.8 0 1 0 8.5 11' stroke='%23c4c4c4' stroke-width='1.3'/><path d='M12 7.8a4.2 4.2 0 1 0 4.2 4.2' stroke='%239a9a9a' stroke-width='1.4'/><path d='M12.6 11.4L18.2 5.8' stroke='%239a9a9a' stroke-width='1.4'/><path d='M15.4 5.4H18.6V8.6' stroke='%239a9a9a' stroke-width='1.4'/></svg>") no-repeat center / contain !important;
  pointer-events:none;
}
.msg-reply-block-detached > *{
  display:inline !important; flex:0 1 auto !important; min-width:0 !important;
  color:var(--ry-search-ink) !important;
  font-size:11px !important; font-weight:700 !important; font-style:normal !important;
  background:transparent !important; margin:0 2px 0 0 !important; line-height:1.3 !important;
  white-space:nowrap !important;
}
.msg-reply-detached-text,
.msg-reply-detached-media{
  max-width:44vw !important; overflow:hidden !important; text-overflow:ellipsis !important;
}
.msg-reply-detached-name::after{ content:"" !important; }

/* ==========================================================
   4. 翻译(WeChat 修复版)  点气泡展开/收起
   ========================================================== */
.msg-translation-wrapper{
  position:static !important; height:0 !important; min-height:0 !important;
  margin:0 !important; padding:0 !important; line-height:0 !important;
  background:transparent !important; border:0 !important; overflow:visible !important;
}
.msg-translation-wrapper .msg-translation-content{ display:none !important; }

.msg-translation-btn{
  position:absolute !important; inset:0 !important;
  top:0 !important; left:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; transform:none !important;
